package main

import (
	"fmt"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookRequest represents the expected JSON payload
type WebhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// WebhookResponse represents the JSON response structure
type WebhookResponse struct {
	Status  string `json:"status"`
	Message string `json:"message"`
}

// In-memory storage to simulate saving the configuration
var savedWebhookURL string

// ConfigureWebhook handles POST requests to configure and validate a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req WebhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Status:  "error",
			Message: "invalid JSON payload",
		})
	}

	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Status:  "error",
			Message: "webhook_url is required",
		})
	}

	// Create an HTTP client with a strict 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a test GET request to validate the webhook URL
	resp, err := client.Get(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadGateway).JSON(WebhookResponse{
			Status:  "error",
			Message: fmt.Sprintf("failed to validate webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Consider only 2xx status codes as successful validation
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadGateway).JSON(WebhookResponse{
			Status:  "error",
			Message: fmt.Sprintf("webhook URL validation failed with status: %d", resp.StatusCode),
		})
	}

	// Save the configuration (simulated in-memory storage)
	savedWebhookURL = req.WebhookURL

	return ctx.Status(fiber.StatusOK).JSON(WebhookResponse{
		Status:  "success",
		Message: "webhook configured and validated successfully",
	})
}

func main() {
	app := fiber.New()

	// Register the handler
	app.Post("/configure-webhook", ConfigureWebhook)

	// Start the server
	if err := app.Listen(":3000"); err != nil {
		fmt.Printf("Server failed to start: %v\n", err)
	}
}

