	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsUnspecified() {
			return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
				"success": false,
				"error":   "webhook URL must not point to internal or private IP addresses",
			})
		}
	}

	// 🔒 SECURITY FIX: Create HTTP client with timeout, redirect blocking, and SSRF-safe dialer
	client := &http.Client{
		Timeout: 5 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Block redirects to prevent SSRF bypass via open redirects
			return fmt.Errorf("redirects are not allowed")
		},
		Transport: &http.Transport{
			DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
				// 🔒 SECURITY FIX: Re-validate IP during dial to prevent DNS rebinding attacks
				dialHost, _, err := net.SplitHostPort(addr)
				if err != nil {
